structure.mermaidSource:
flowchart TD
  start["Início: Análise da Questão de Oração Desenvolvida"] --> dec_nominalizacao{"A alternativa transformou a oração em nominalização?<br/>(Substantivo abstrato)"}
  dec_nominalizacao -- "Sim" --> res_elim_nominalizacao["Eliminar Alternativa:<br/>Falsa desenvolvida (nominalização)"]
  dec_nominalizacao -- "Não" --> dec_reduzida{"A alternativa manteve forma verbal reduzida?<br/>(Infinitivo, gerúndio ou particípio)"}
  dec_reduzida -- "Sim" --> res_elim_reduzida["Eliminar Alternativa:<br/>Permanece em forma reduzida"]
  dec_reduzida -- "Não" --> dec_correlacao{"Apresenta desvio de correlação temporal com a regente?"}
  dec_correlacao -- "Sim" --> res_elim_correlacao["Eliminar Alternativa:<br/>Incompatibilidade de tempo e modo"]
  dec_correlacao -- "Não" --> dec_conectivo_verbo{"Apresenta conectivo explícito e verbo conjugado no tempo/modo corretos?"}
  dec_conectivo_verbo -- "Sim" --> res_gabarito["Gabarito Confirmado:<br/>Oração Desenvolvida Correta"]
  dec_conectivo_verbo -- "Não" --> res_elim_invalida["Eliminar Alternativa:<br/>Conectivo ausente/errado ou flexão incorreta"]
